@@ -0,0 +1,38 @@
+// Copyright (c) Electron authors.
+// Use of this source code is governed by the MIT license
+// that can be found in the LICENSE file.
+
+#include "shell/common/fuses/application_entry_point.h"
+
+#include "base/json/json_reader.h"
+#include "base/values.h"
+
+namespace electron::fuses {
+
+base::FilePath GetApplicationEntryPointFromPackageJson(
+    const std::string& package_json) {
+  auto value = base::JSONReader::Read(package_json);
+  if (!value || !value->is_dict())
+    return base::FilePath();
+
+  const std::string* main = value->GetDict().FindString("main");
+  const std::string& entry = main ? *main : std::string("index.js");
+  if (entry.empty())
+    return base::FilePath();
+
+  base::FilePath entry_path = base::FilePath::FromUTF8Unsafe(entry);
+  if (entry_path.IsAbsolute() || entry_path.ReferencesParent())
+    return base::FilePath();
+
+  return entry_path;
+}
+
+}  // namespace electron::fuses
