new file mode 100644
index 0000000..0d6dc2d
--- /dev/null
+++ b/src/runtime/safe-url.ts
@@ -0,0 +1,146 @@
+function isHttpProtocol(protocol: string): boolean {
+  return protocol === "http:" || protocol === "https:";
+}
+
+function isLocalHostname(hostname: string): boolean {
+  const normalized = hostname.toLowerCase();
+  return normalized === "localhost" || normalized.endsWith(".localhost");
+}
+
+function parseIpv4(hostname: string): number[] | null {
+  const parts = hostname.split(".");
+  if (parts.length !== 4) return null;
+  const bytes: number[] = [];
+  for (const part of parts) {
+    if (!/^\d+$/.test(part)) return null;
+    if (part.length > 1 && part.startsWith("0")) return null;
+    const value = Number(part);
+    if (!Number.isInteger(value) || value < 0 || value > 255) return null;
+    bytes.push(value);
+  }
+  return bytes;
+}
+
+function isPrivateIpv4(bytes: number[]): boolean {
+  const [a, b] = bytes;
+  return a === 10 ||
+    a === 127 ||
+    a === 0 ||
+    (a === 169 && b === 254) ||
+    (a === 172 && b >= 16 && b <= 31) ||
+    (a === 192 && b === 168);
+}
+
+function normalizeIpv6(hostname: string): string {
+  return hostname.toLowerCase();
+}
+
+function isIpv6(hostname: string): boolean {
+  return hostname.includes(":");
+}
+
+function isPrivateIpv6(hostname: string): boolean {
+  const normalized = normalizeIpv6(hostname);
+
+  if (
+    normalized === "::1" ||
+    normalized === "::" ||
+    normalized.startsWith("fc") ||
+    normalized.startsWith("fd") ||
+    normalized.startsWith("fe80:")
+  ) {
+    return true;
+  }
+
+  if (normalized.startsWith("::ffff:")) {
+    const mapped = normalized.slice("::ffff:".length);
+    const ipv4 = parseIpv4(mapped);
+    return ipv4 != null && isPrivateIpv4(ipv4);
+  }
+
+  return false;
+}
+
+export function isSafeRemoteUrl(value: string): boolean {
+  let url: URL;
+  try {
+    url = new URL(value);
+  } catch {
+    return false;
+  }
+
+  if (!isHttpProtocol(url.protocol)) return false;
+  if (url.hostname === "") return false;
+  if (isLocalHostname(url.hostname)) return false;
+
+  const ipv4 = parseIpv4(url.hostname);
+  if (ipv4 != null) return !isPrivateIpv4(ipv4);
+
+  if (isIpv6(url.hostname)) return !isPrivateIpv6(url.hostname);
+
+  return true;
+}
