diff --git a/packages/nextjs/src/utils/envelopeRequestUrl.ts b/packages/nextjs/src/utils/envelopeRequestUrl.ts
new file mode 100644
index 0000000..2dfd17f
--- /dev/null
+++ b/packages/nextjs/src/utils/envelopeRequestUrl.ts
@@ -0,0 +1,33 @@
+import { dsnFromString, makeDsn } from '@sentry/utils';
+
+/**
+ * Returns the Sentry envelope endpoint URL for a valid DSN.
+ *
+ * This intentionally derives the upstream URL from a parsed DSN instead of
+ * trusting an arbitrary URL-shaped string, preventing proxying to non-Sentry
+ * paths, querystrings, or fragments supplied by user input.
+ */
+export function envelopeRequestUrl(dsn: string): string {
+  const parsedDsn = dsnFromString(dsn);
+
+  if (!parsedDsn) {
+    throw new Error('Invalid DSN');
+  }
+
+  const normalizedDsn = makeDsn(parsedDsn);
+
+  if (!normalizedDsn) {
+    throw new Error('Invalid DSN');
+  }
+
+  const url = new URL(normalizedDsn);
+  const projectId = url.pathname.replace(/^\//, '').split('/').pop();
+
+  if (!projectId) {
+    throw new Error('Invalid DSN');
+  }
+
+  url.pathname = `/api/${projectId}/envelope/`;
+  url.search = '';
+  url.hash = '';
+  return url.toString();
+}

