@@ -0,0 +1,43 @@
+<?php
+
+namespace MongoDB\Monitoring;
+
+use function MongoDB\is_monitoring_command_allowed;
+
+/**
+ * Register a command subscriber while suppressing authentication-related
+ * commands from being forwarded to userland listeners.
+ */
+function addSubscriber(CommandSubscriber $subscriber): void
+{
+    \MongoDB\Driver\Monitoring\addSubscriber(new class($subscriber) implements \MongoDB\Driver\Monitoring\CommandSubscriber {
+        private $subscriber;
+
+        public function __construct(CommandSubscriber $subscriber)
+        {
+            $this->subscriber = $subscriber;
+        }
+
+        public function commandStarted($event): void
+        {
+            if (is_monitoring_command_allowed($event->getCommandName())) {
+                $this->subscriber->commandStarted($event);
+            }
+        }
+
+        public function commandSucceeded($event): void
+        {
+            if (is_monitoring_command_allowed($event->getCommandName())) {
+                $this->subscriber->commandSucceeded($event);
+            }
+        }
+
+        public function commandFailed($event): void
+        {
+            if (is_monitoring_command_allowed($event->getCommandName())) {
+                $this->subscriber->commandFailed($event);
+            }
+        }
+    });
+}
