--- /dev/null
+++ b/src/data/url.ts
@@ -0,0 +1,38 @@
+export const normalizeLink = (link: string | null | undefined) => {
+  if (!link) {
+    return null;
+  }
+
+  const trimmedLink = link.trim();
+  if (!trimmedLink) {
+    return null;
+  }
+
+  // Allow relative URLs and safe protocols. Disallow executable protocols
+  // such as `javascript:` and `data:` to prevent XSS when links are rendered.
+  if (
+    /^[a-zA-Z][a-zA-Z\d+\-.]*:/.test(trimmedLink)
+  ) {
+    try {
+      const url = new URL(trimmedLink);
+      const protocol = url.protocol.toLowerCase();
+      if (
+        protocol !== "http:" &&
+        protocol !== "https:" &&
+        protocol !== "mailto:" &&
+        protocol !== "tel:"
+      ) {
+        return null;
+      }
+      return trimmedLink;
+    } catch {
+      return null;
+    }
+  }
+
+  if (
+    trimmedLink.startsWith("/") ||
+    trimmedLink.startsWith("./") ||
+    trimmedLink.startsWith("../") ||
+    trimmedLink.startsWith("#")
+  ) {
+    return trimmedLink;
+  }
+  return null;
+};

