+import { describe, expect, it, vi } from 'vitest';
+import { resolveRequestHandlers } from './resolve-request-handlers';
+
+describe('resolveRequestHandlers', () => {
+  it('allows safe cross-origin requests', async () => {
+    const handler = vi.fn();
+    const requestEv: any = {
+      request: new Request('https://app.example.com/test', {
+        method: 'GET',
+        headers: {
+          origin: 'https://evil.example.com',
+        },
+      }),
+      url: new URL('https://app.example.com/test'),
+      error: (status: number, message: string) => {
+        const err: any = new Error(message);
+        err.status = status;
+        return err;
+      },
+    };
+
+    await resolveRequestHandlers(requestEv, [handler]);
+    expect(handler).toHaveBeenCalledTimes(1);
+  });
+
+  it('allows same-origin state-changing requests', async () => {
+    const handler = vi.fn();
+    const requestEv: any = {
+      request: new Request('https://app.example.com/test', {
+        method: 'POST',
+        headers: {
+          origin: 'https://app.example.com',
+        },
+      }),
+      url: new URL('https://app.example.com/test'),
+      error: (status: number, message: string) => {
+        const err: any = new Error(message);
+        err.status = status;
+        return err;
+      },
+    };
+
+    await resolveRequestHandlers(requestEv, [handler]);
+    expect(handler).toHaveBeenCalledTimes(1);
+  });
+
+  it('rejects cross-origin state-changing requests', async () => {
+    const handler = vi.fn();
+    const requestEv: any = {
+      request: new Request('https://app.example.com/test', {
+        method: 'POST',
+        headers: {
+          origin: 'https://evil.example.com',
+        },
+      }),
+      url: new URL('https://app.example.com/test'),
+      error: (status: number, message: string) => {
+        const err: any = new Error(message);
+        err.status = status;
+        return err;
+      },
+    };
+
+    await expect(resolveRequestHandlers(requestEv, [handler])).rejects.toMatchObject({
+      status: 403,
+    });
+    expect(handler).not.toHaveBeenCalled();
+  });
+});

