+// Converts dangerous HTML entity encoded angle brackets into full-width forms
+// to prevent pasted content like &#60;script&#62; from becoming executable HTML
+// when inserted into the editor.
+export const code160To32 = (value: string) => {
+    if (!value) {
+        return value;
+    }
+
+    return value
+        .replace(/&#0*60;/gi, "＜")
+        .replace(/&#x0*3c;/gi, "＜")
+        .replace(/&#0*62;/gi, "＞")
+        .replace(/&#x0*3e;/gi, "＞");
+};
